const products=[
{id:'good-key',name:'按压解压小物',en:'PRESS & RELAX',type:'press',format:'打印成品',color:'#ddd1eb',art:'key',desc:'按一下，给思绪放个小假。',detail:'围绕机械按压触感展开的产品类别。具体造型、规格与配件以商品正式发布为准。',mark:'01'},
{id:'cloud-key',name:'按键挂饰',en:'TAKE JOY WITH YOU',type:'press',format:'打印成品',color:'#f6dfab',art:'cloud',desc:'把一朵软乎乎的好心情，挂在身边。',detail:'将按键玩法带在身边的挂饰类别。具体产品照片、规格与配件以正式发布为准。',mark:'02'},
{id:'spin-ring',name:'旋转解压小物',en:'ROUND & ROUND',type:'spin',format:'打印成品',color:'#f1c6b5',art:'spin',desc:'手指转一圈，日常多一点轻松。',detail:'围绕手指旋转玩法展开的解压小物类别。具体造型、结构与配件以正式发布为准。',mark:'03'},
{id:'good-file',name:'数字设计文件',en:'MAKE YOUR OWN GOOD',type:'file',format:'数字文件',color:'#cfdfcd',art:'file',desc:'用自己的打印机，让一个好点子成形。',detail:'面向希望自行打印和组装的使用者。商品照片、文件格式、配件及授权范围以正式发布为准。',mark:'04'}];
function art(p){if(p.type==='file')return `<span class="photo-slot"><span class="slot-type">虚拟商品</span><strong>设计预览图预留</strong><small>自行打印 · 不含实体产品</small></span>`;return `<span class="photo-slot"><span class="slot-type">${p.format}</span><strong>产品照片预留</strong><small>等待实物亮相</small></span>`}
let cart={};try{const saved=JSON.parse(localStorage.getItem('ogs-cart-v1')||'{}');for(const p of products){const q=saved[p.id];if(Number.isInteger(q)&&q>0)cart[p.id]=Math.min(q,99)}}catch{}
let filter='all';const qs=s=>document.querySelector(s);const count=()=>Object.values(cart).reduce((a,b)=>a+b,0);
function renderProducts(){if(!qs('#products'))return;qs('#products').innerHTML=products.filter(p=>document.body.dataset.catalog==='digital'?p.type==='file':p.type!=='file'&&(filter==='all'||p.type===filter)).map(p=>`<article class="product-card"><button class="product-art" style="background:${p.color}" data-detail="${p.id}" aria-label="查看${p.name}详情">${art(p)}<span class="card-stamp">${p.format}</span><span class="art-index">OGS / ${p.mark}</span></button><div class="product-info"><div class="product-meta"><span>${p.en}</span><span>商品类别</span></div><h3><button class="title-link" data-detail="${p.id}">${p.name}</button></h3><p>${p.desc}</p><div class="card-bottom"><span>NT$ · 售价未公布</span><button class="add" data-add="${p.id}" aria-label="将${p.name}加入体验购物车">＋</button></div></div></article>`).join('')}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===value||(value==='physical'&&b.dataset.filter==='all');b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});renderProducts()}
function persist(){try{localStorage.setItem('ogs-cart-v1',JSON.stringify(cart))}catch{}renderCart();if(qs('#checkout-main'))renderCheckout();}
function renderCart(){if(qs('#checkout-link')){qs('#checkout-link').hidden=!count();qs('#checkout-link').style.display=count()?'flex':'none';}qs('#cart-count').textContent=count();qs('#drawer-count').textContent=count();qs('#cart-items').innerHTML=count()?products.filter(p=>cart[p.id]).map(p=>`<article class="cart-row"><div class="cart-thumb" style="background:${p.color}" aria-hidden="true"><span>照片<br>预留</span></div><div><h3>${p.name}</h3><p>${p.format} · 商品类别 · NT$ · 售价未公布</p><div class="qty"><button data-qty="${p.id}" data-change="-1" aria-label="减少${p.name}数量">−</button><span aria-label="数量">${cart[p.id]}</span><button data-qty="${p.id}" data-change="1" aria-label="增加${p.name}数量" ${cart[p.id]>=99?'disabled':''}>＋</button><button class="remove" data-remove="${p.id}">移除</button></div></div></article>`).join(''):'<div class="empty"><span>✳</span>购物车里，还差一点小快乐。</div>'}
let toastTimer;function toast(message){qs('#toast').textContent=message;qs('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>qs('#toast').classList.remove('show'),2500)}
function add(id){if(!products.some(p=>p.id===id))return;const amount=qs('#product-quantity')?Number(qs('#product-quantity').value):1;if(!Number.isInteger(amount)||amount<1||amount>99){qs('#product-quantity')?.reportValidity();return;}cart[id]=Math.min((cart[id]||0)+amount,99);persist();toast('已加入体验购物车 · 当前不生成订单')}
function detail(id){const p=products.find(x=>x.id===id);if(!p)return;if(p.type!=='file'){location.href='product.html?id='+encodeURIComponent(id);return;}qs('#product-detail').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en}</span><h2>${p.name}</h2><p>${p.detail}</p><span class="pill">${p.format}</span><p class="detail-note">${p.type==='file'?'设计预览图预留。虚拟商品，不含实体产品。':'产品照片预留。'}暂未开售，以新台币计价；价格、规格及交付内容以正式发布为准。</p><button class="button yellow" data-add="${p.id}">加入体验购物车</button></div></div>`;qs('#product-dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter)setFilter(b.dataset.filter);if(b.dataset.select){setFilter(b.dataset.select==='all'?'physical':b.dataset.select);(qs('#shop')||qs('#designs')).scrollIntoView({behavior:'smooth'})}if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.add)add(b.dataset.add);if(b.dataset.qty){const id=b.dataset.qty;cart[id]=Math.max(0,Math.min(99,(cart[id]||0)+Number(b.dataset.change)));if(!cart[id])delete cart[id];persist()}if(b.dataset.remove){delete cart[b.dataset.remove];persist()}if(b.hasAttribute('data-close'))b.closest('dialog').close()});
qs('#open-cart').onclick=()=>{renderCart();qs('#cart-dialog').showModal()};qs('#keep-shopping').onclick=()=>{qs('#cart-dialog').close();const catalog=qs('#shop')||qs('#designs');if(catalog)catalog.scrollIntoView({behavior:'smooth'});else location.href='products.html';};qs('#open-info').onclick=()=>qs('#info-dialog').showModal();
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
qs('#year').textContent=new Date().getFullYear();renderProducts();renderCart();

// Only set this to the owner's verified public creator-profile URL.
const makerWorldProfile = 'https://makerworld.com/zh/@OGStudio';
const profileSlot = qs('#makerworld-profile');
if(profileSlot && /^https:\/\/(www\.)?makerworld\.(com|cn)\//.test(makerWorldProfile)){
const link=document.createElement('a');link.className='button mint';link.href=makerWorldProfile;link.target='_blank';link.rel='noopener noreferrer';link.textContent='我的 MakerWorld 设计主页';profileSlot.append(link);profileSlot.hidden=false;
}

const currentPage=document.body.dataset.page;
const pageLinks={home:'index.html',products:'products.html',designs:'design-files.html',about:'about.html',product:'products.html'};
document.querySelectorAll('header nav a,.catalog-nav a').forEach(a=>{if(a.getAttribute('href')===pageLinks[currentPage])a.setAttribute('aria-current','page')});
if(qs('#full-product')){
 const id=new URLSearchParams(location.search).get('id');const p=products.find(p=>p.id===id&&p.type!=='file');
 if(!p){qs('#full-product').innerHTML='<h1>没有找到这件商品。</h1><p>请返回实体产品页，重新选择。</p><a class="button yellow" href="products.html">浏览实体产品</a>';}
 else{document.title=p.name+' — One Goods Studio';qs('#full-product').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en} / ${p.type==='press'?'按压派':'旋转派'}</span><h1>${p.name}</h1><span class="pill">实体产品</span><p>${p.detail}</p><p><strong>NT$ · 售价未公布</strong></p><label class="quantity-field">数量 <input id="product-quantity" type="number" value="1" min="1" max="99" required inputmode="numeric"></label><button class="button yellow" data-add="${p.id}">加入体验购物车</button><a class="text-button" href="checkout.html">查看结账体验</a><p class="detail-note">产品照片、材质、尺寸及配送信息以正式发布为准。当前尚未开售，体验购物车不会生成订单。</p></div></div>`;}
}
function checkoutItems(){return products.filter(p=>cart[p.id]);}
function checkoutStep(step){['contact','review','payment'].forEach((name,i)=>{qs('#step-'+name)?.classList.toggle('active',i===step)});}
function renderCheckout(){
 if(!qs('#checkout-main'))return;
 qs('#checkout-items').innerHTML=checkoutItems().map(p=>`<div class="summary-item"><span>${p.name} × ${cart[p.id]}<br><small>${p.format}</small></span><span>NT$ · 售价未公布</span></div>`).join('');
 checkoutStep(0);
 if(!count()){qs('#checkout-main').innerHTML='<div class="empty"><span>✳</span>购物车里还没有商品。<br><a class="button yellow cart-empty-link" href="products.html">浏览实体产品</a></div>';return;}
 const physical=checkoutItems().some(p=>p.type!=='file');
 qs('#checkout-main').innerHTML=`<form class="checkout-form" id="contact-form"><h2>${physical?'配送与联系资料':'联系资料'}</h2><p class="wide form-note">此为流程体验，请使用虚构资料。填写内容仅留在本页，不会上传或保存。</p><label>收件人姓名<input name="fullName" autocomplete="off" required maxlength="80" placeholder="体验姓名"></label><label>电子邮件<input name="email" type="email" autocomplete="off" required maxlength="120" placeholder="demo@example.com"></label>${physical?'<label class="wide">联系电话<input name="phone" type="tel" autocomplete="off" required maxlength="40" placeholder="体验用联系电话"></label><label class="wide">收件地址<input name="address" autocomplete="off" required maxlength="300" placeholder="体验用地址"></label><p class="wide form-note">配送范围、配送方式与运费以正式开售时公布的信息为准。</p>':'<p class="wide form-note">数字商品不需要实体配送，交付内容与下载方式以商品说明为准。</p>'}<button class="button yellow wide" type="submit">下一步：核对订单</button></form>`;
 qs('#contact-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const contact={name:f.get('fullName'),email:f.get('email'),phone:f.get('phone'),address:f.get('address')};renderReview(contact);});
}
function renderReview(contact){checkoutStep(1);qs('#checkout-main').innerHTML='<section class="checkout-review"><h2>核对订单</h2><span class="pill">结账流程体验</span><p id="contact-preview"></p><p>请核对右侧商品与数量。商品金额、配送费用及付款方式尚未公布，当前不能提交真实订单。</p><button class="text-button" id="edit-contact">返回修改资料</button><button class="button yellow" id="payment-preview">下一步：付款说明</button></section>';
 qs('#contact-preview').textContent=[contact.name,contact.email,contact.phone,contact.address].filter(Boolean).join('\n');
 qs('#edit-contact').onclick=()=>{renderCheckout();const form=qs('#contact-form');for(const [key,value] of Object.entries({fullName:contact.name,email:contact.email,phone:contact.phone,address:contact.address})){if(form.elements[key]&&value)form.elements[key].value=value;}};
 qs('#payment-preview').onclick=()=>{checkoutStep(2);qs('#checkout-main').innerHTML='<section class="checkout-review"><h2>付款说明</h2><span class="pill">新台币 TWD / NT$</span><p>商品尚未开售，当前没有可用的付款方式。本次体验不会生成订单，也不会收款。</p><p>正式下单前，请确认商品售价、配送费用、付款方式和退换货说明。</p><button class="button yellow" disabled>暂未开售，无法提交订单</button><a class="text-button" href="products.html">返回实体产品</a></section>';};
}
renderCheckout();
